			if stdErr == nil && zjErr == nil && (!reflect.DeepEqual(&stdRaw, &zjRaw)) {
				t.Fatalf("raw decode value divergence\ninput: %q\nstdlib: %#v\nzerojson: %#v", data, &stdRaw, &zjRaw)
			}
